import { hashPassword } from './auth.js';
import { getActiveRules } from './ranking.js';

// Same schema the original EF Core model created, so either backend works on the same database.
// Only runs when the tables don't exist yet; existing data is never touched.
const DDL = `
CREATE TABLE IF NOT EXISTS "Users" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY,
  "Email" character varying(256) NOT NULL,
  "PasswordHash" character varying(512) NOT NULL,
  "Role" character varying(20) NOT NULL,
  "IsActive" boolean NOT NULL,
  "CreatedAt" timestamp with time zone NOT NULL,
  "LastLoginAt" timestamp with time zone NULL,
  CONSTRAINT "PK_Users" PRIMARY KEY ("Id")
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_Users_Email" ON "Users" ("Email");

CREATE TABLE IF NOT EXISTS "RankingRules" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY,
  "Name" character varying(80) NOT NULL,
  "WinPoints" integer NOT NULL,
  "LossPoints" integer NOT NULL,
  "MarginBonusThreshold" integer NOT NULL,
  "MarginBonusPoints" integer NOT NULL,
  "StreakBonusThreshold" integer NOT NULL,
  "StreakBonusPoints" integer NOT NULL,
  "MinMatchesToRank" integer NOT NULL,
  "AllowNegativePoints" boolean NOT NULL,
  "IsActive" boolean NOT NULL,
  "UpdatedAt" timestamp with time zone NOT NULL,
  "UpdatedByUserId" integer NULL,
  CONSTRAINT "PK_RankingRules" PRIMARY KEY ("Id"),
  CONSTRAINT "CK_RankingRules_NonNegative" CHECK ("WinPoints" >= 0 AND "MarginBonusThreshold" >= 0 AND "StreakBonusThreshold" >= 0 AND "MinMatchesToRank" >= 1)
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_RankingRules_IsActive" ON "RankingRules" ("IsActive") WHERE "IsActive" = TRUE;

CREATE TABLE IF NOT EXISTS "Players" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY,
  "UserId" integer NULL,
  "FullName" character varying(120) NOT NULL,
  "Gender" character varying(10) NOT NULL,
  "Age" integer NOT NULL,
  "SkillLevel" character varying(20) NOT NULL,
  "PlayingCategory" character varying(20) NOT NULL,
  "DateRegistered" timestamp with time zone NOT NULL,
  "UpdatedAt" timestamp with time zone NOT NULL,
  "IsActive" boolean NOT NULL,
  "PhotoUpdatedAt" timestamp with time zone NULL,
  CONSTRAINT "PK_Players" PRIMARY KEY ("Id"),
  CONSTRAINT "CK_Players_Age" CHECK ("Age" BETWEEN 5 AND 120),
  CONSTRAINT "FK_Players_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE SET NULL
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_Players_UserId" ON "Players" ("UserId");
CREATE INDEX IF NOT EXISTS "IX_Players_FullName" ON "Players" ("FullName");
CREATE INDEX IF NOT EXISTS "IX_Players_IsActive_SkillLevel_Gender" ON "Players" ("IsActive", "SkillLevel", "Gender");

CREATE TABLE IF NOT EXISTS "PlayerPhotos" (
  "PlayerId" integer NOT NULL,
  "Data" bytea NOT NULL,
  "ContentType" character varying(50) NOT NULL,
  "UpdatedAt" timestamp with time zone NOT NULL,
  CONSTRAINT "PK_PlayerPhotos" PRIMARY KEY ("PlayerId"),
  CONSTRAINT "FK_PlayerPhotos_Players_PlayerId" FOREIGN KEY ("PlayerId") REFERENCES "Players" ("Id") ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS "Matches" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY,
  "MatchType" character varying(10) NOT NULL,
  "Category" character varying(10) NOT NULL,
  "Status" character varying(12) NOT NULL,
  "PlayedAt" timestamp with time zone NOT NULL,
  "Location" character varying(150) NULL,
  "Notes" character varying(1000) NULL,
  "CreatedByUserId" integer NOT NULL,
  "CreatedAt" timestamp with time zone NOT NULL,
  "UpdatedAt" timestamp with time zone NOT NULL,
  CONSTRAINT "PK_Matches" PRIMARY KEY ("Id"),
  CONSTRAINT "CK_Matches_MixedIsDoubles" CHECK ("Category" <> 'Mixed' OR "MatchType" = 'Doubles'),
  CONSTRAINT "FK_Matches_Users_CreatedByUserId" FOREIGN KEY ("CreatedByUserId") REFERENCES "Users" ("Id") ON DELETE RESTRICT
);
CREATE INDEX IF NOT EXISTS "IX_Matches_CreatedByUserId" ON "Matches" ("CreatedByUserId");
CREATE INDEX IF NOT EXISTS "IX_Matches_PlayedAt" ON "Matches" ("PlayedAt");
CREATE INDEX IF NOT EXISTS "IX_Matches_Status_PlayedAt" ON "Matches" ("Status", "PlayedAt");

CREATE TABLE IF NOT EXISTS "MatchParticipants" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY,
  "MatchId" integer NOT NULL,
  "PlayerId" integer NOT NULL,
  "Team" integer NOT NULL,
  CONSTRAINT "PK_MatchParticipants" PRIMARY KEY ("Id"),
  CONSTRAINT "CK_MatchParticipants_Team" CHECK ("Team" IN (1, 2)),
  CONSTRAINT "FK_MatchParticipants_Matches_MatchId" FOREIGN KEY ("MatchId") REFERENCES "Matches" ("Id") ON DELETE CASCADE,
  CONSTRAINT "FK_MatchParticipants_Players_PlayerId" FOREIGN KEY ("PlayerId") REFERENCES "Players" ("Id") ON DELETE RESTRICT
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_MatchParticipants_MatchId_PlayerId" ON "MatchParticipants" ("MatchId", "PlayerId");
CREATE INDEX IF NOT EXISTS "IX_MatchParticipants_PlayerId" ON "MatchParticipants" ("PlayerId");

CREATE TABLE IF NOT EXISTS "MatchResults" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY,
  "MatchId" integer NOT NULL,
  "Team1Score" integer NOT NULL,
  "Team2Score" integer NOT NULL,
  "WinningTeam" integer NOT NULL,
  "RecordedByUserId" integer NOT NULL,
  "RecordedAt" timestamp with time zone NOT NULL,
  "UpdatedByUserId" integer NULL,
  "UpdatedAt" timestamp with time zone NULL,
  CONSTRAINT "PK_MatchResults" PRIMARY KEY ("Id"),
  CONSTRAINT "CK_MatchResults_Scores" CHECK ("Team1Score" >= 0 AND "Team2Score" >= 0),
  CONSTRAINT "CK_MatchResults_NoTie" CHECK ("Team1Score" <> "Team2Score"),
  CONSTRAINT "CK_MatchResults_Winner" CHECK ("WinningTeam" IN (1, 2)),
  CONSTRAINT "FK_MatchResults_Matches_MatchId" FOREIGN KEY ("MatchId") REFERENCES "Matches" ("Id") ON DELETE CASCADE,
  CONSTRAINT "FK_MatchResults_Users_RecordedByUserId" FOREIGN KEY ("RecordedByUserId") REFERENCES "Users" ("Id") ON DELETE RESTRICT,
  CONSTRAINT "FK_MatchResults_Users_UpdatedByUserId" FOREIGN KEY ("UpdatedByUserId") REFERENCES "Users" ("Id") ON DELETE RESTRICT
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_MatchResults_MatchId" ON "MatchResults" ("MatchId");
CREATE INDEX IF NOT EXISTS "IX_MatchResults_RecordedByUserId" ON "MatchResults" ("RecordedByUserId");
CREATE INDEX IF NOT EXISTS "IX_MatchResults_UpdatedByUserId" ON "MatchResults" ("UpdatedByUserId");

CREATE TABLE IF NOT EXISTS "MatchResultHistory" (
  "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
  "MatchId" integer NOT NULL,
  "Action" character varying(30) NOT NULL,
  "ChangedByUserId" integer NOT NULL,
  "ChangedAt" timestamp with time zone NOT NULL,
  "Reason" character varying(500) NULL,
  "PreviousValues" jsonb NULL,
  "NewValues" jsonb NULL,
  CONSTRAINT "PK_MatchResultHistory" PRIMARY KEY ("Id"),
  CONSTRAINT "FK_MatchResultHistory_Matches_MatchId" FOREIGN KEY ("MatchId") REFERENCES "Matches" ("Id") ON DELETE CASCADE,
  CONSTRAINT "FK_MatchResultHistory_Users_ChangedByUserId" FOREIGN KEY ("ChangedByUserId") REFERENCES "Users" ("Id") ON DELETE RESTRICT
);
CREATE INDEX IF NOT EXISTS "IX_MatchResultHistory_ChangedByUserId" ON "MatchResultHistory" ("ChangedByUserId");
CREATE INDEX IF NOT EXISTS "IX_MatchResultHistory_MatchId_ChangedAt" ON "MatchResultHistory" ("MatchId", "ChangedAt");

CREATE TABLE IF NOT EXISTS "Leaderboard" (
  "Id" integer GENERATED BY DEFAULT AS IDENTITY,
  "PlayerId" integer NOT NULL,
  "Scope" character varying(20) NOT NULL,
  "Rank" integer NOT NULL,
  "PreviousRank" integer NULL,
  "MatchesPlayed" integer NOT NULL,
  "Wins" integer NOT NULL,
  "Losses" integer NOT NULL,
  "WinPercentage" numeric(5,2) NOT NULL,
  "Points" integer NOT NULL,
  "CurrentWinStreak" integer NOT NULL,
  "LongestWinStreak" integer NOT NULL,
  "PointsFor" integer NOT NULL,
  "PointsAgainst" integer NOT NULL,
  "LastMatchAt" timestamp with time zone NULL,
  "UpdatedAt" timestamp with time zone NOT NULL,
  CONSTRAINT "PK_Leaderboard" PRIMARY KEY ("Id"),
  CONSTRAINT "CK_Leaderboard_Counts" CHECK ("Wins" >= 0 AND "Losses" >= 0 AND "MatchesPlayed" = "Wins" + "Losses"),
  CONSTRAINT "FK_Leaderboard_Players_PlayerId" FOREIGN KEY ("PlayerId") REFERENCES "Players" ("Id") ON DELETE CASCADE
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_Leaderboard_PlayerId_Scope" ON "Leaderboard" ("PlayerId", "Scope");
CREATE INDEX IF NOT EXISTS "IX_Leaderboard_Scope_Rank" ON "Leaderboard" ("Scope", "Rank");
`;

let initPromise = null;

/** Runs once per serverless instance: schema (if missing), default rules, first admin. */
export function ensureInitialized(db) {
  initPromise ??= initialize(db).catch((err) => {
    initPromise = null;
    throw err;
  });
  return initPromise;
}

async function initialize(db) {
  const exists = await db.scalar(`SELECT to_regclass('public."Users"') IS NOT NULL`);
  if (!exists) {
    await db.tx(async (t) => {
      await t.query('SELECT pg_advisory_xact_lock(727273)');
      for (const stmt of DDL.split(';').map((s) => s.trim()).filter(Boolean)) await t.query(stmt);
    });
    console.log('Database schema created.');
  }

  await db.tx((t) => getActiveRules(t));

  const hasAdmin = await db.scalar(`SELECT EXISTS (SELECT 1 FROM "Users" WHERE "Role" = 'Admin')`);
  if (hasAdmin) return;

  const email = (process.env.ADMIN_EMAIL || process.env.Admin__Email || '').trim().toLowerCase();
  const password = process.env.ADMIN_PASSWORD || process.env.Admin__Password || '';
  if (!email || password.length < 8) {
    console.warn('No administrator exists. Set ADMIN_EMAIL and ADMIN_PASSWORD (min 8 chars) and redeploy to create one.');
    return;
  }

  const existing = await db.one('SELECT "Id" FROM "Users" WHERE "Email" = $1', [email]);
  if (existing) {
    await db.query(`UPDATE "Users" SET "Role" = 'Admin', "IsActive" = TRUE WHERE "Id" = $1`, [existing.Id]);
    console.log(`Promoted existing user ${email} to Admin.`);
    return;
  }

  await db.query(
    `INSERT INTO "Users" ("Email", "PasswordHash", "Role", "IsActive", "CreatedAt")
     VALUES ($1, $2, 'Admin', TRUE, now()) ON CONFLICT ("Email") DO NOTHING`,
    [email, await hashPassword(password)],
  );
  console.log(`Created administrator account ${email}.`);
}
